export class LinkProvider{constructor(t,e,n,i={},r=1){this._terminal=t,this._regex=e,this._handler=n,this._options=i,this._matchIndex=r}provideLinks(t,e){e(computeLink(t,this._regex,this._terminal,this._matchIndex).map(t=>Object.assign({range:t.range,text:t.text,activate:this._handler},this._options)))}}export const computeLink=(t,e,n,i=1)=>{const r=new RegExp(e.source,((e.flags||"")+"g").split("").filter((t,e,n)=>n.indexOf(t)===e).join("")),[s,o]=translateBufferLineToStringWithWrap(t-1,n);let a,c=-1;const f=[];for(;null!==(a=r.exec(s));){const t=a[i];if(!t){console.log("match found without corresponding matchIndex");break}if(c=s.indexOf(t,c+1),r.lastIndex=c+t.length,c<0)break;const e={start:stringIndexToBufferPosition(n,o,c),end:stringIndexToBufferPosition(n,o,c+t.length-1,!0)};f.push({range:e,text:t})}return f};const translateBufferLineToStringWithWrap=(t,e)=>{let n,i,r="";do{const n=e.buffer.active.getLine(t);if(!n)break;n.isWrapped&&t--,i=n.isWrapped}while(i);const s=t;do{const i=e.buffer.active.getLine(t+1);n=!!i&&i.isWrapped;const s=e.buffer.active.getLine(t);if(!s)break;r+=s.translateToString(!0).substring(0,e.cols),t++}while(n);return[r,s]},stringIndexToBufferPosition=(t,e,n,i=!1)=>{const r=t.buffer.active.getNullCell();for(;n;){const s=t.buffer.active.getLine(e);if(!s)return{x:0,y:0};const o=s.length;for(let t=0;t<o;){if(s.getCell(t,r),(n-=r.getChars().length)<0)return{x:t+(i?r.getWidth():1),y:e+1};t+=r.getWidth()}e++}return{x:1,y:e+1}};